exec('import csv,os,requests\nrows=list(csv.DictReader(open("signals_history.csv",encoding="utf-8")))\nlatest=max(r["date"] for r in rows)\nselected=[r for r in rows if r["date"]==latest and r["signal"] in ("ACHAT","SURCHAUFFE","SURVEILLANCE HAUTE","FAIBLESSE FORTE")]\nlines=["INVESTMENT ASSISTANT",f"Date des cours : {latest}",""]\nfor r in selected:\n devise="EUR" if r["ticker"].endswith((".PA",".AS")) else "USD"\n lines.append(r["signal"]+" | "+r["ticker"]+" | Cloture J-1 : "+r["price"]+" "+devise+" | Score "+r["score"]+"/100 | Var5j "+r["var5"]+"% | RSI "+r["rsi14"]+" | RVOL "+r["rvol"])\nif not selected: lines.append("Aucun signal prioritaire pour la derniere seance analysee.")\nlines.extend(["","Analyse basee sur la cloture J-1.","Signaux experimentaux en paper trading. Aucun ordre reel."])\nmessage="\\n\\n".join(lines)\nr=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":message},timeout=30)\nprint("Telegram alert:",r.status_code,r.json().get("ok"))')
